// ── Normalize Email ──────────────────────────────────────
const item = $input.item.json;

// Extract raw fields from Gmail Trigger output
const rawFrom   = item.from   || '';
const subject   = item.subject || '(Sin asunto)';
const bodyHtml  = item.html   || '';
const bodyText  = item.text   || '';
const threadId  = item.threadId || item.id || '';
const messageId = item.id    || '';
const date      = item.date  || new Date().toISOString();
const snippet   = item.snippet || '';

// Parse "Name <email>" format
const emailMatch = rawFrom.match(/<([^>]+)>/);
const fromEmail  = (emailMatch ? emailMatch[1] : rawFrom).toLowerCase().trim();
const fromName   = rawFrom.replace(/<[^>]+>/, '').replace(/"/g, '').trim();

// Extract domain
const domain = fromEmail.includes('@') ? fromEmail.split('@')[1].toLowerCase() : '';

// Strip HTML to plain text
function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const body = (bodyText || stripHtml(bodyHtml)).substring(0, 8000);

// ── Detect automated / non-human emails ──────────────────
const AUTOMATED_EMAIL_PATTERNS = [
  /^(no-?reply|noreply|donotreply|do-not-reply|mailer-daemon|postmaster|bounce|auto-?mail)/i,
  /^(notifications?|alerts?|newsletter|digest|unsubscribe|marketing|news)@/i,
  /^(info|hello|support|help)@(mailchimp|constantcontact|sendgrid|hubspot)/i
];

const AUTOMATED_SUBJECT_PATTERNS = [
  /^(out of office|automatic reply|auto-?reply|delivery status|undelivered mail|mailer-daemon|receipt|order confirmation|your (order|receipt|invoice|subscription))/i,
  /^\[?(spam|bulk|junk)\]?/i
];

const AUTOMATED_DOMAINS = [
  'mailchimp.com', 'constantcontact.com', 'sendgrid.net', 'amazonses.com',
  'bounce.', 'mailgun.org', 'postmarkapp.com', 'sparkpostmail.com',
  'mandrillapp.com', 'exacttarget.com', 'salesforce.com', 'marketo.com',
  'hubspotemail.net'
];

const isAutomatedByEmail   = AUTOMATED_EMAIL_PATTERNS.some(p => p.test(fromEmail));
const isAutomatedBySubject = AUTOMATED_SUBJECT_PATTERNS.some(p => p.test(subject));
const isAutomatedByDomain  = AUTOMATED_DOMAINS.some(d => domain.includes(d));
const isAutomatedByHeader  = body.toLowerCase().includes('x-mailer:') ||
                             body.toLowerCase().includes('list-unsubscribe');

const isAutomated = isAutomatedByEmail || isAutomatedBySubject ||
                    isAutomatedByDomain || isAutomatedByHeader;

// ── Return normalized object ──────────────────────────────
return {
  from_email:   fromEmail,
  from_name:    fromName,
  domain:       domain,
  subject:      subject,
  body:         body,
  body_html:    bodyHtml.substring(0, 16000),
  thread_id:    threadId,
  message_id:   messageId,
  date:         date,
  snippet:      snippet,
  is_automated: isAutomated,
  raw_from:     rawFrom
};

// ── Extract QuickBooks Customer Data ─────────────────────
const qbResponse  = $input.item.json;
const emailData   = $('Normalize Email').item.json;

const queryResponse = qbResponse.QueryResponse || {};
const customers     = queryResponse.Customer   || [];

if (customers.length === 0) {
  return {
    customer_found: false,
    from_email:     emailData.from_email,
    from_name:      emailData.from_name,
    domain:         emailData.domain,
    subject:        emailData.subject,
    body:           emailData.body,
    thread_id:      emailData.thread_id,
    message_id:     emailData.message_id,
    date:           emailData.date
  };
}

const c = customers[0];

return {
  customer_found:          true,
  quickbooks_customer_id:  String(c.Id || ''),
  customer_name:           c.DisplayName || c.FullyQualifiedName || emailData.from_name,
  company_name:            c.CompanyName || '',
  customer_email:          (c.PrimaryEmailAddr && c.PrimaryEmailAddr.Address) || emailData.from_email,
  customer_phone:          (c.PrimaryPhone && c.PrimaryPhone.FreeFormNumber) || '',
  balance:                 c.Balance != null ? c.Balance : 0,
  balance_with_jobs:       c.BalanceWithJobs != null ? c.BalanceWithJobs : 0,
  is_active:               c.Active !== false,
  notes:                   c.Notes || '',
  // pass through email data
  from_email:              emailData.from_email,
  from_name:               emailData.from_name,
  domain:                  emailData.domain,
  subject:                 emailData.subject,
  body:                    emailData.body,
  thread_id:               emailData.thread_id,
  message_id:              emailData.message_id,
  date:                    emailData.date
};

