// ── Summarize Gmail Thread ───────────────────────────────
const threadData   = $input.item.json;
const customerData = $('Extract Customer Data').item.json;

function decodeBase64(str) {
  try {
    return Buffer.from(str.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8');
  } catch(e) {
    return '';
  }
}

function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

function extractBody(payload) {
  if (!payload) return '';
  const parts = payload.parts || [];
  if (payload.body && payload.body.data) {
    return decodeBase64(payload.body.data);
  }
  for (const part of parts) {
    if (part.mimeType === 'text/plain' && part.body && part.body.data) {
      return decodeBase64(part.body.data);
    }
  }
  for (const part of parts) {
    if (part.mimeType === 'text/html' && part.body && part.body.data) {
      return stripHtml(decodeBase64(part.body.data));
    }
  }
  return '';
}

function getHeader(headers, name) {
  const h = (headers || []).find(h => h.name.toLowerCase() === name.toLowerCase());
  return h ? h.value : '';
}

const messages = (threadData.messages || []).slice(-20);

const summaryItems = messages.map((msg, idx) => {
  const headers = (msg.payload && msg.payload.headers) || [];
  const from    = getHeader(headers, 'From');
  const date    = getHeader(headers, 'Date');
  const subj    = getHeader(headers, 'Subject');
  const body    = extractBody(msg.payload).substring(0, 600);
  return `[${idx + 1}] De: ${from} | Fecha: ${date}\nAsunto: ${subj}\n${body}\n`;
});

const threadSummary = summaryItems.join('\n---\n').substring(0, 6000);

return {
  ...customerData,
  thread_summary:   threadSummary,
  thread_msg_count: messages.length
};

// ── Assemble AI Prompt ───────────────────────────────────
// Gather data from upstream nodes
const threadData   = $('Summarize Thread').first().json;
const policiesData = $('Load Company Policies').all();
const lessonsData  = $('Load Relevant Lessons').all();

// Format policies
const policies = policiesData.map(p => {
  const d = p.json;
  return `- [${d.category?.toUpperCase()}] ${d.policy_name}: ${d.policy_text}`;
}).join('\n');

// Format lessons
const lessons = lessonsData.length > 0
  ? lessonsData.map(l => {
      const d = l.json;
      return `- Situación: ${d.situation_type || 'general'} → Lección: ${d.lesson}`;
    }).join('\n')
  : 'Sin lecciones previas registradas para este cliente.';

// Format customer data
const balanceWarning = threadData.balance > 0
  ? `⚠️ BALANCE VENCIDO: $${threadData.balance}`
  : 'Sin balance pendiente.';

const customerInfo = `
- Nombre: ${threadData.customer_name || 'Desconocido'}
- Empresa: ${threadData.company_name || 'No especificada'}
- Email: ${threadData.from_email}
- QB ID: ${threadData.quickbooks_customer_id || 'N/A'}
- Estado cuenta: ${threadData.is_active ? 'Activo' : 'Inactivo'}
- ${balanceWarning}
- Notas internas: ${threadData.notes || 'Ninguna'}`;

// System prompt
const systemPrompt = `Eres el asistente interno de VIP Tech Consulting, una empresa de tecnología y consultoría.
Tu trabajo es redactar respuestas profesionales a clientes, equilibrando excelente servicio con protección comercial.

REGLAS CRÍTICAS:
- No prometas descuentos, entregas, cambios fuera de scope ni responsabilidades no confirmadas.
- No inventes información que no tengas disponible.
- Si falta información crítica, propón una respuesta prudente que compre tiempo para investigar.
- El email que generes es para revisión humana, NO para envío automático.
- Responde siempre en español, tono profesional y cercano.
- Tu respuesta DEBE ser JSON válido con exactamente los campos especificados.

POLÍTICAS INTERNAS DE LA EMPRESA:
${policies}

LECCIONES DE INTERACCIONES PREVIAS CON ESTE CLIENTE:
${lessons}`;

// User prompt
const userPrompt = `DATOS DEL CLIENTE:
${customerInfo}

EMAIL RECIBIDO:
Fecha: ${threadData.date}
Asunto: ${threadData.subject}
---
${threadData.body}
---

HISTORIAL RESUMIDO DEL THREAD (últimos ${threadData.thread_msg_count} mensajes):
${threadData.thread_summary || 'Sin historial previo en este thread.'}

GENERA UN JSON con EXACTAMENTE esta estructura (sin texto fuera del JSON):
{
  "case_summary": "Resumen breve y claro del caso en 2-3 oraciones",
  "risk_level": "bajo|medio|alto",
  "risk_reason": "Explicación breve del nivel de riesgo",
  "suggested_reply_subject": "Re: ${threadData.subject}",
  "suggested_reply_body": "El cuerpo completo del email de respuesta, listo para enviar",
  "reasoning_for_human": "Explicación de por qué elegiste esta respuesta y qué consideraciones tuviste",
  "human_review_notes": [
    "Punto 1 que el humano debe verificar antes de enviar",
    "Punto 2 que el humano debe verificar antes de enviar"
  ]
}`;

return [{
  json: {
    system_prompt: systemPrompt,
    user_prompt:   userPrompt,
    // pass through all context
    ...threadData,
    policies_loaded: policiesData.length,
    lessons_loaded:  lessonsData.length
  }
}];

// ── Parse OpenAI Response ────────────────────────────────
const openAiOutput = $input.item.json;
const contextData  = $('Assemble AI Prompt').first().json;

// Extract the message content
const rawContent = openAiOutput.message?.content ||
                   openAiOutput.choices?.[0]?.message?.content ||
                   openAiOutput.content ||
                   '{}';

let aiResult;
try {
  aiResult = JSON.parse(rawContent);
} catch (e) {
  // Fallback if JSON parsing fails
  aiResult = {
    case_summary: 'Error al parsear respuesta de IA. Revisar manualmente.',
    risk_level: 'alto',
    risk_reason: 'No se pudo procesar la respuesta de IA.',
    suggested_reply_subject: 'Re: ' + contextData.subject,
    suggested_reply_body: 'Estimado/a ' + contextData.customer_name + ',\n\nHemos recibido su mensaje y lo estamos revisando. Le responderemos a la brevedad.\n\nGracias por su paciencia.\n\nAtentamente,\nEquipo VIP Tech Consulting',
    reasoning_for_human: 'Respuesta generada por fallback. La IA no pudo procesar el contexto correctamente.',
    human_review_notes: ['Revisar respuesta manualmente - IA tuvo error de procesamiento']
  };
}

// Risk level mapping to emoji
const riskEmoji = {
  'bajo':   '🟢',
  'medio':  '🟡',
  'alto':   '🔴',
  'low':    '🟢',
  'medium': '🟡',
  'high':   '🔴'
};

const riskLevel = (aiResult.risk_level || 'medio').toLowerCase();

return {
  // AI output
  case_summary:            aiResult.case_summary || '',
  risk_level:              riskLevel,
  risk_emoji:              riskEmoji[riskLevel] || '🟡',
  risk_reason:             aiResult.risk_reason || '',
  suggested_reply_subject: aiResult.suggested_reply_subject || ('Re: ' + contextData.subject),
  suggested_reply_body:    aiResult.suggested_reply_body || '',
  reasoning_for_human:     aiResult.reasoning_for_human || '',
  human_review_notes:      aiResult.human_review_notes || [],
  raw_ai_response:         rawContent,
  // Customer / email context (pass through)
  message_id:              contextData.message_id,
  thread_id:               contextData.thread_id,
  from_email:              contextData.from_email,
  from_name:               contextData.from_name,
  subject:                 contextData.subject,
  body:                    contextData.body,
  quickbooks_customer_id:  contextData.quickbooks_customer_id || '',
  customer_name:           contextData.customer_name || '',
  company_name:            contextData.company_name || '',
  balance:                 contextData.balance || 0
};

// ── Merge draft_id from Create Gmail Draft ───────────────
const aiData   = $('Parse AI Response').first().json;
const draftRes = $('Create Gmail Draft').first().json;

// Gmail Draft create returns: { id, message: { id, threadId, labelIds } }
const draftId = draftRes.id || draftRes.message?.id || 'DRAFT_ID_ERROR';

return [{
  json: {
    ...aiData,
    draft_id: draftId
  }
}];

